<?php ?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lavash N1 • Kuryer Kabineti</title><style>
:root{--bg:#070b12;--panel:#101722;--card:#ffffff;--ink:#111827;--muted:#667085;--brand:#ff4d00;--brand2:#ff8a00;--line:#e6e8ec;--ok:#12b76a;--danger:#f04438;--shadow:0 24px 70px #00000022}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Arial;background:linear-gradient(180deg,#070b12 0 300px,#f5f7fb 300px);color:var(--ink)}button,input{font:inherit}.wrap{max-width:1180px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center;color:#fff;padding:18px 0}.brand{display:flex;align-items:center;gap:10px;font-weight:1000;font-size:23px}.brand .logo{width:46px;height:46px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(135deg,var(--brand),var(--brand2));box-shadow:0 14px 35px #ff4d0040}.status{display:flex;align-items:center;gap:8px;color:#b8f6d4;font-weight:900}.dot{width:9px;height:9px;background:var(--ok);border-radius:50%;box-shadow:0 0 0 6px #12b76a18}.hero{background:linear-gradient(135deg,#121a27,#1d2939);color:#fff;border:1px solid #ffffff12;border-radius:28px;padding:28px;box-shadow:0 30px 90px #00000030;position:relative;overflow:hidden}.hero:after{content:'🌯';position:absolute;right:35px;top:18px;font-size:90px;opacity:.11;transform:rotate(-12deg)}.hero h1{margin:0 0 8px;font-size:32px}.hero p{margin:0;color:#cbd5e1}.view{display:flex;gap:10px;margin-top:18px}.btn{border:0;border-radius:14px;padding:11px 15px;font-weight:900;cursor:pointer}.primary{background:linear-gradient(135deg,var(--brand),var(--brand2));color:#fff;box-shadow:0 12px 28px #ff4d0035}.dark{background:#111827;color:#fff}.light{background:#fff;color:#344054;border:1px solid #d0d5dd}.danger{background:#fee4e2;color:#b42318}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}.card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow)}.label{color:var(--muted);font-weight:800}.metric{font-size:28px;font-weight:1000;margin-top:6px}.sectionTitle{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:18px 0 10px}.sectionTitle h2{margin:0}.panel{margin-top:14px}.orders{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.order{background:#fff;border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:0 14px 40px #1018280b}.orderHead{display:flex;justify-content:space-between;gap:10px}.orderId{font-size:18px;font-weight:1000}.pill{display:inline-block;border-radius:999px;padding:6px 10px;font-size:12px;font-weight:900}.p-delivery{background:#cffafe;color:#155e75}.p-prep{background:#ede9fe;color:#5b21b6}.p-confirmed{background:#dbeafe;color:#1d4ed8}.meta{display:grid;gap:6px;color:#475467;margin:12px 0}.amount{font-size:21px;font-weight:1000}.map{margin-top:10px;border-radius:16px;overflow:hidden;border:1px solid #e5e7eb}.map iframe{display:block;width:100%;height:190px;border:0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.history{display:grid;gap:10px;max-height:520px;overflow:auto}.historyItem{padding:14px;border:1px solid var(--line);border-radius:16px;background:#fff}.login{min-height:calc(100vh - 36px);display:grid;place-items:center}.loginCard{width:min(460px,100%);background:#fff;border-radius:28px;padding:28px;box-shadow:0 30px 90px #00000022}.field{margin-top:12px}.field label{display:block;font-weight:900;margin-bottom:6px}.field input{width:100%;padding:13px 14px;border-radius:14px;border:1px solid #d0d5dd;outline:none}.field input:focus{border-color:var(--brand);box-shadow:0 0 0 4px #ff4d0014}.error{margin-top:10px;background:#fef3f2;border:1px solid #fecdca;color:#b42318;border-radius:14px;padding:11px;font-weight:800}.muted{color:var(--muted)}.empty{text-align:center;padding:35px 15px;color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.orders{grid-template-columns:1fr}}@media(max-width:600px){body{background:linear-gradient(180deg,#070b12 0 260px,#f5f7fb 260px)}.wrap{padding:12px}.hero{padding:22px}.hero h1{font-size:25px}.grid{grid-template-columns:1fr 1fr}.metric{font-size:22px}.top{padding:10px 0}.brand{font-size:19px}.hero:after{font-size:70px;right:10px}.actions .btn{width:100%}}
</style></head><body><div class="wrap"><header class="top"><div class="brand"><div class="logo">🛵</div><div>Lavash N1<br><small style="font-size:12px;color:#94a3b8">Kuryer Kabineti</small></div></div><div id="topStatus" class="status"><span class="dot"></span> Server tekshirilmoqda...</div></header><div id="app"></div></div><script>
const TOKEN_KEY='lavash_n1_courier_token_v3',app=document.getElementById('app'),topStatus=document.getElementById('topStatus');
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(action,opts={}){const token=localStorage.getItem(TOKEN_KEY)||'';const sep=action.includes('?')?'&':'?';const query=token?'&token='+encodeURIComponent(token):'';const r=await fetch('courier_api.php?action='+encodeURIComponent(action)+sep+'_t='+Date.now()+query,{...opts,cache:'no-store'});const text=await r.text();let d;try{d=JSON.parse(text)}catch(e){throw new Error('Server JSON javob bermadi (HTTP '+r.status+')')};return d}
function login(message=''){app.innerHTML='<div class="login"><div class="loginCard"><div class="brand" style="color:#111827;margin-bottom:16px"><div class="logo">🛵</div><div>Lavash N1<br><small style="font-size:12px;color:#667085">Kuryerga kirish</small></div></div><h1 style="margin:0 0 6px">Xush kelibsiz 👋</h1><p class="muted">Buyurtmalar, xarita va yetkazib berish shu yerda boshqariladi.</p><div class="field"><label>Login</label><input id="loginUser" autocomplete="username" placeholder="Daler"></div><div class="field"><label>Parol</label><input id="loginPass" type="password" autocomplete="current-password" placeholder="Lavash"></div><button id="loginBtn" class="btn primary" style="width:100%;margin-top:14px">Kirish</button><div id="loginErr" class="error" style="display:'+(message?'block':'none')+'">'+esc(message)+'</div></div></div>';document.getElementById('loginBtn').onclick=doLogin;}
async function doLogin(){const b=document.getElementById('loginBtn'),e=document.getElementById('loginErr');b.disabled=true;b.textContent='Tekshirilmoqda...';e.style.display='none';try{const f=new FormData();f.append('login',document.getElementById('loginUser').value.trim());f.append('password',document.getElementById('loginPass').value);const d=await api('login',{method:'POST',body:f});if(!d.ok)throw new Error(d.message||'Login yoki parol noto‘g‘ri.');localStorage.setItem(TOKEN_KEY,d.token);await loadDashboard()}catch(x){e.textContent=x.message;e.style.display='block'}finally{b.disabled=false;b.textContent='Kirish'}}
function mapHtml(x){const lat=Number(x.lat),lng=Number(x.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return '<div class="muted">📍 Mijoz lokatsiyasi tasdiqlanmagan</div>';const q=encodeURIComponent(lat+','+lng);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><div class="actions"><a class="btn dark" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Yo‘lni ochish</a></div>'}
function statusBadge(s){const m={confirmed:['Tasdiqlangan','p-confirmed'],preparing:['Tayyorlanmoqda','p-prep'],delivering:['Yo‘lda','p-delivery']};const [t,c]=m[s]||[s,'p-confirmed'];return '<span class="pill '+c+'">'+esc(t)+'</span>'}
async function loadDashboard(){try{const m=await api('me');if(!m.ok){localStorage.removeItem(TOKEN_KEY);login(m.message||'Kirish kerak.');return}const [s,o,h]=await Promise.all([api('summary'),api('orders'),api('history')]);if(!s.ok||!o.ok||!h.ok)throw new Error((!s.ok&&s.message)||(!o.ok&&o.message)||(!h.ok&&h.message)||'Ma’lumotlarni yuklashda xato');const d=s.data||{},orders=o.data||[],history=h.data||[];topStatus.innerHTML='<span class="dot"></span> ONLINE • serverga ulangan';app.innerHTML='<div class="hero"><h1>'+esc(m.data?.name||'Daler Lavash')+'</h1><p>Bugungi ish davri: '+esc(d.business_start||'06:00')+' → '+esc(d.business_end||'00:00')+'</p><div class="view"><button class="btn primary" onclick="loadDashboard()">↻ Yangilash</button><button class="btn light" onclick="logout()">Chiqish</button></div></div><div class="grid"><div class="card"><div class="label">Faol buyurtmalar</div><div class="metric">'+orders.length+'</div></div><div class="card"><div class="label">Bugungi savdo</div><div class="metric">'+Number(d.sales||0).toLocaleString('uz-UZ')+' so‘m</div></div><div class="card"><div class="label">Yetkazilgan</div><div class="metric">'+Number(d.completed||0)+'</div></div><div class="card"><div class="label">Ish davri</div><div class="metric">06:00–00:00</div></div></div><div class="sectionTitle"><h2>🛵 Faol buyurtmalar</h2><span class="muted">'+orders.length+' ta</span></div><div class="orders">'+(orders.map(x=>'<article class="order"><div class="orderHead"><div class="orderId">#'+x.id+' • '+esc(x.customer_name)+'</div>'+statusBadge(x.status)+'</div><div class="meta"><div>📞 <a href="tel:'+esc(x.phone||'')+'">'+esc(x.phone||'')+'</a></div><div>📍 '+esc(x.address||'Manzil ko‘rsatilmagan')+'</div><div>💳 '+((x.payment_method||'cash')==='card'?'Karta':'Naqd')+'</div><div class="amount">💰 '+Number(x.amount||0).toLocaleString('uz-UZ')+' so‘m</div></div>'+mapHtml(x)+'<div class="actions"><button class="btn primary" onclick="setStatus('+x.id+',\'delivering\')">🛵 Yo‘lga chiqish</button><button class="btn dark" onclick="setStatus('+x.id+',\'completed\')">✅ Yetkazildi</button></div></article>').join('')||'<div class="card empty">Hozircha sizga biriktirilgan faol buyurtma yo‘q.</div>')+'</div><div class="panel"><div class="sectionTitle"><h2>🧾 Buyurtma tarixi</h2><span class="muted">So‘nggi '+history.length+' ta</span></div><div class="card history">'+(history.map(x=>'<div class="historyItem"><b>#'+x.id+' • '+esc(x.customer_name)+'</b><br><span class="muted">'+new Date(x.created_at).toLocaleString('uz-UZ')+' • '+esc(x.status)+'</span><br><b>'+Number(x.amount||0).toLocaleString('uz-UZ')+' so‘m</b> • '+(((x.payment_method||'cash')==='card')?'Karta':'Naqd')+'</div>').join('')||'<div class="empty">Buyurtma tarixi hozircha bo‘sh.</div>')+'</div></div>'}catch(e){topStatus.innerHTML='<span style="color:#fda29b">● Ulanish muammosi</span>';app.innerHTML='<div class="card error"><b>Kuryer panel yuklanmadi.</b><br>'+esc(e.message)+'<br><br><button class="btn primary" onclick="loadDashboard()">↻ Qayta urinish</button></div>'}}
async function setStatus(id,status){try{const f=new FormData();f.append('order_id',id);f.append('status',status);const d=await api('status',{method:'POST',body:f});if(!d.ok)throw new Error(d.message||'Status saqlanmadi');await loadDashboard()}catch(e){alert(e.message)}}
async function logout(){try{await api('logout')}finally{localStorage.removeItem(TOKEN_KEY);login()}}
(async()=>{try{const h=await api('health');topStatus.innerHTML=h.database?'<span class="dot"></span> ONLINE • server + baza':'<span style="color:#fdb022">● Server online • baza kutilyapti</span>'}catch(e){topStatus.innerHTML='<span style="color:#fda29b">● Server ulanmagan</span>'}const t=localStorage.getItem(TOKEN_KEY);t?loadDashboard():login()})();setInterval(()=>{if(localStorage.getItem(TOKEN_KEY))loadDashboard()},15000);
</script></body></html>